from .api import PmRestApi
from .exceptions import ItemNotFoundInResponse
from .time_filter import TimeFilter


class Pm:

    def __init__(self, web_url, username, password):
        self.api = PmRestApi(web_url, username, password)
        self._adaptation = {}

    @property
    def adaptations(self):
        """
        Get and store the adaptations of all technologies.

        Example format::

         {
            'LNBTS-NSN LTE Base Transceiver Station':
                {
                    'content':
                        {
                            'counters': True,
                            'customKPIs': False,
                            'sharedKPIs': False,
                            'systemKPIs': False
                        },
                    'description': 'LNBTS-NSN LTE Base Transceiver Station',
                    'id': 'NOKLTE',
                    'modificationTime': '2022-02-25T05:55:17+02:00',
                    'releaseId': 'rslte'
                },
            'NRBTS-Nokia AirScale BTS 5G':
                {
                    'content':
                        {
                            'counters': True,
                            'customKPIs': False,
                            'sharedKPIs': False,
                            'systemKPIs': False
                        },
                    'description': 'NRBTS-Nokia AirScale BTS 5G',
                    'id': 'NOKGNB',
                    'modificationTime': '2022-02-25T05:27:53+02:00',
                    'releaseId': 'nokgnb'}, ...
            }

        :return: Technology adaptations.
        :rtype: dict
        """
        if not self._adaptation:
            response = self.api.get_adaptations()
            self._parse_adaptations(response)
        return self._adaptation

    def _parse_adaptations(self, response):
        for outer_item in response:
            if 'contentReleases' in outer_item:
                content_releases = outer_item.pop('contentReleases')
                for inner_item in content_releases:
                    inner_item['id'] = outer_item['id']
                    self._adaptation[inner_item['description']] = inner_item
            self._adaptation[outer_item['description']] = outer_item

    def get_technology(self, technology):
        """
        Get technology adaptation by its description.

        Example output::

            {
                'content':
                    {
                        'counters': True,
                        'customKPIs': False,
                        'sharedKPIs': False,
                        'systemKPIs': False
                    },
                'description': 'LNBTS-NSN LTE Base Transceiver Station',
                'id': 'NOKLTE',
                'modificationTime': '2022-02-25T05:55:17+02:00',
                'releaseId': 'rslte'
            }

        :param string technology: Technology name, e.g., `LNBTS-NSN LTE Base Transceiver Station`.
        :return: Technology adaptation.
        :rtype: dict
        """
        if technology in self.adaptations:
            return self.adaptations[technology]
        else:
            raise ItemNotFoundInResponse(
                'description', [technology], list(self.adaptations.values()))

    def get_adaptation_id(self, technology):
        """
        Get technology adaptation id by its description.

        :param string technology: Technology name, e.g., `LNBTS-NSN LTE Base Transceiver Station`.
        :return: Technology adaptation id, e.g., `NOKLTE`.
        :rtype: string
        """
        return self.get_technology(technology)['id']

    def get_release_id(self, technology):
        """
        Get technology release id by its description.

        :param string technology: Technology name, e.g., `NBTS-NSN LTE Base Transceiver Station`.
        :return: Technology release id, e.g, `rslte`.
        :rtype: string
        """
        return self.get_technology(technology)['releaseId']

    @staticmethod
    def _get_items_from_response(response, item_name, item_values):
        if isinstance(item_values, str):
            item_values = [item_values]
        found_items = [item for item in response if item[item_name] in item_values]
        found_item_values = [item[item_name] for item in found_items]
        not_found_item_values = [item for item in item_values if item not in found_item_values]
        if not_found_item_values:
            raise ItemNotFoundInResponse(item_name, not_found_item_values, response)
        return found_items

    def prepare_counter_columns(self, technology, measurement, counters):
        """
        Prepare schemes of counter columns.

        Example output::

            [
                {
                    'baseLevel': 'RSLTE-LNCEL',
                    'deprecated': False,
                    'id': 'CHNG_TO_CELL_AVAIL',
                    'measurementReference': 'rslte:counters:LCELAV',
                    'name': 'CHNG_TO_CELL_AVAIL (M8020C0)',
                    'omesName': 'LTE_Cell_Avail',
                    'reference': 'rslte:counters:LCELAV#CHNG_TO_CELL_AVAIL'
                }
            ]

        :param string technology: Technology name, e.g., `LNBTS-NSN LTE Base Transceiver Station`.
        :param string measurement: Measurement name, e.g., `LTE Cell Availability`.
        :param string|list(string) counters: Counter identifier(s), e.g.,
            `CHNG_TO_CELL_AVAIL` or `['CHNG_TO_CELL_AVAIL', 'CHNG_TO_CELL_PLAN_UNAVAIL']`.
            Accepts also `ALL` what means all counters of the set `measurement`.
        :return: Schemes of counter columns.
        :rtype: list(dict)
        """
        adaptation_id = self.get_adaptation_id(technology)
        release_id = self.get_release_id(technology)
        measurement_response = self.api.get_measurements(adaptation_id, release_id)
        measurement_reference = self._get_items_from_response(
            measurement_response, item_name='name', item_values=measurement)[0]['reference']
        counters_response = self.api.get_counters(adaptation_id, release_id, measurement_reference)
        if isinstance(counters, str) and counters.upper() == 'ALL':
            return counters_response
        else:
            return self._get_items_from_response(
                counters_response, item_name='id', item_values=counters)

    def prepare_kpi_columns(self, technology, kpis, kpis_type='all', shared=False):
        """
        Prepare schemes of KPI columns.

        Example output::

            [
                {
                    'adaptation': 'NOKBCU',
                    'alias': 'Cell Avail',
                    'deprecated': False,
                    'id': 'BCU_1a',
                    'name': 'Cell Availability',
                    'permissions': ['GET'],
                    'reference': 'nokbcu:kpis:BCU_1a#BCU_1a',
                    'release': 'nokbcu',
                    'shared': True,
                    'unit': '%'
                }
            ]


        :param string technology: Technology name, e.g., `LNBTS-NSN LTE Base Transceiver Station`
        :param string|list(string) kpis: KPI identifier(s), e.g.,
            `CHNG_TO_CELL_AVAIL` or `['CHNG_TO_CELL_AVAIL', 'CHNG_TO_CELL_PLAN_UNAVAIL']`.
        :param string kpis_type: The type of reports. Allowed values: ''all'', ''custom'' and ''system''
        :param bool shared: Specifies if shared KPIs should be taken into account
        :return: Schemes of KPI columns.
        :rtype: list(dict)
        """
        adaptation_id = self.get_adaptation_id(technology)
        release_id = self.get_release_id(technology)
        kpis_response = self.api.get_kpis(adaptation_id, release_id, kpis_type, shared)
        return self._get_items_from_response(kpis_response, item_name='id', item_values=kpis)

    def get_object_level(self, reference, filter_by):
        """
        Get object level.

        :param string reference: Counter or KPI reference, e.g., `rslte:counters:LCELAV#CHNG_TO_CELL_AVAIL`.
        :param string filter_by: Item from `Filer by` list at `Object selection` stage
            of `Add To Ne Board` wizard, e.g., `MRBTS`.
        :return: Object level, e.g., `RSLTE-MRBTS`
        :rtype: string
        """
        response = self.api.get_object_levels(reference)
        return self._get_items_from_response(
            response, item_name='name', item_values=filter_by)[0]['id']

    def prepare_object_filters(self, technology, object_level, mo_names):
        """
        Prepare schemes of object filters.

        Example output::

            [
                {
                    'dn': 'PLMN-PLMN/MRBTS-1',
                    'id': '111111',
                    'name': 'PLMN-PLMN/MRBTS-1',
                    'objectLevel': 'RSLTE-MRBTS',
                    'type': 'managed'
                }
            ]

        :param string technology: Technology name, e.g., `LNBTS-NSN LTE Base Transceiver Station`.
        :param string object_level: Value returned by `get_object_level`, e.g., `RSLTE-MRBTS`.
        :param string|list(string) mo_names: Managed object name(s), e.g., `PLMN-PLMN/MRBTS-1`
            or `['PLMN-PLMN/MRBTS-1', 'PLMN-PLMN/MRBTS-2']`.
            Item from `Available objects` list at `Object selection` stage of `Add To New Board` wizard.
        :return: Schemes of object filters.
        :rtype: list(dict)
        """
        release_id = self.get_release_id(technology)
        response = self.api.get_object_instances(release_id, object_level)
        return self._get_items_from_response(
            response, item_name='name', item_values=mo_names)

    def prepare_network_dimension(self, reference, object_aggregation):
        """
        Prepare network dimension scheme.

        Example output::

            {
                'externalName': 'PLMN/MRBTS',
                'id': 'PLMN/RSLTE-MRBTS',
                'name': 'PLMN/MRBTS',
                'objectType': 'managed',
                'type': 'network'
            }

        :param string reference: Counter or KPI reference, e.g., `rslte:counters:LCELAV#CHNG_TO_CELL_AVAIL`.
        :param string object_aggregation: Object aggregation name, e.g., `PLMN/MRBTS`.
            Item from `Object` list at `Aggregation` stage of `Add To New Board` wizard.
        :return: Network dimension scheme.
        :rtype: dict
        """
        response = self.api.get_network_dimensions(reference)
        network_dimension = self._get_items_from_response(
            response, item_name='name', item_values=object_aggregation)[0]
        return network_dimension

    def prepare_time_dimension(self, reference, aggregation_level, object_level, time_aggregation):
        """
        Prepare time dimension scheme.

        Example output::

            {
                'id': 'raw',
                'name': 'RAW',
                'type': 'time'
            }

        :param string reference: Counter or KPI reference, e.g., `rslte:counters:LCELAV#CHNG_TO_CELL_AVAIL`.
        :param string aggregation_level: Network dimension id, e.g., `PLMN/RSLTE-MRBTS`.
        :param string object_level: Value returned by `get_object_level`, e.g., `RSLTE-MRBTS`.
        :param string time_aggregation: Time aggregation name, e.g., `RAW`.
            Item from `Time` list at `Aggregation` stage of `Add To New Board` wizard.
        :return: Time dimension scheme.
        :rtype: dict
        """
        response = self.api.get_time_dimensions(reference, aggregation_level, object_level)
        time_dimension = self._get_items_from_response(
            response, item_name='name', item_values=time_aggregation)[0]
        time_dimension["type"] = "time"
        return time_dimension

    @staticmethod
    def _convert_report(report):
        return [dict(zip(report['headers'], row)) for row in report['rows']]

    def get_counters_report(self, technology, measurement, counters, filter_by, mo_names,
                            object_aggregation, time_aggregation, time_filter='absolute', **kwargs):
        """
        Perform on-the-fly report and return PM counters statistics.

        Configuration of parameters and their values correspond to the `Add To New Board` wizard \
        of `Performance Manage+` application.
        Technology, measurement and counter identifier are accessible in `View Details` of each counter.

        .. note::

            No idea how to configure parameter?
            Just set a dummy value, run script and follow a hint returned in the exception.

        Example output::

            [
                {
                    'CHNG_TO_CELL_AVAIL': 1.0,
                    'CHNG_TO_CELL_PLAN_UNAVAIL': 1.0,
                    'dn': 'PLMN-PLMN/MRBTS-1/LNBTS-1/LNCEL-1',
                    'lnbts_name': '1',
                    'lncel_gid': '100011',
                    'lncel_name': '1',
                    'mrbts_name': '1',
                    'period_start_time': '2022-02-22 09:00:00.0'
                },
                {
                    'CHNG_TO_CELL_AVAIL': 0.0,
                    'CHNG_TO_CELL_PLAN_UNAVAIL': 1.0,
                    'dn': 'PLMN-PLMN/MRBTS-1/LNBTS-1/LNCEL-2',
                    'lnbts_name': '1',
                    'lncel_gid': '100012',
                    'lncel_name': '2',
                    'mrbts_name': '1',
                    'period_start_time': '2022-02-22 09:00:00.0'
                },
                {
                    'CHNG_TO_CELL_AVAIL': 1.0,
                    'CHNG_TO_CELL_PLAN_UNAVAIL': 2.0,
                    'dn': 'PLMN-PLMN/MRBTS-1/LNBTS-1/LNCEL-3',
                    'lnbts_name': '1',
                    'lncel_gid': '100013',
                    'lncel_name': '3',
                    'mrbts_name': '1',
                    'period_start_time': '2022-02-22 09:00:00.0'
                }
            ]

        :param string technology: Technology name, e.g., ``LNBTS-NSN LTE Base Transceiver Station``
        :param string measurement: Measurement name, e.g., ``LTE Cell Availability``
        :param string|list(string) counters: Counter identifier(s), e.g.,
            ``CHNG_TO_CELL_AVAIL`` or ``['CHNG_TO_CELL_AVAIL', 'CHNG_TO_CELL_PLAN_UNAVAIL']``.
            Accepts also ``ALL`` what means all counters of the set ``measurement``.
        :param string filter_by: Item from `Filer by` list at `Object selection` stage
            of `Add To New Board` wizard, e.g., ``MRBTS``.
        :param string|list(string) mo_names: Managed object name(s), e.g., ``PLMN-PLMN/MRBTS-1``
            or ``['PLMN-PLMN/MRBTS-1', 'PLMN-PLMN/MRBTS-2']``.
            Item from `Available objects` list at `Object selection` stage of `Add To New Board` wizard.
        :param string object_aggregation: Object aggregation name, e.g., ``PLMN/MRBTS``.
            Item from `Object` list at `Aggregation` stage of `Add To New Board` wizard.
        :param string time_aggregation: Time aggregation name, e.g., ``RAW``.
            Item from `Time` list at `Aggregation` stage of `Add To New Board` wizard.
        :param string time_filter: Corresponds to `Time selection` stage of `Add To New Board` wizard.
            Allowed value: ``relative``, ``absolute``, ``realtime``, ``today``, ``currentMonth``
            or ``previousMonth``.

        :kwargs: Depend on the set ``time_filter`` as follows:

            - time_from (string): Mandatory for ``relative`` time filter.
                Allowed values: ``NOW`` or ``MIDNIGHT``.
            - time_amount (int): Mandatory for ``relative`` time filter.
            - time_period (string): Mandatory for ``relative`` time filter.
                Allowed values: ``MIN``, ``HOUR``, ``DAY``, ``WEEK`` or ``MONTH``.
            - start_time (datetime): Mandatory for ``absolute`` time filter.
            - end_time (datetime): Mandatory for ``absolute`` time filter.
            - look_back_period (int): Mandatory for ``realtime`` time filter (in minutes).

        :return: PM counters statistics.
        :rtype: list(dict)
        """
        time_filter = TimeFilter(time_filter, **kwargs).scheme
        columns = self.prepare_counter_columns(technology, measurement, counters)
        counter_reference = columns[0]['reference']
        object_level = self.get_object_level(counter_reference, filter_by)
        object_filters = self.prepare_object_filters(technology, object_level, mo_names)
        network_dimension = self.prepare_network_dimension(counter_reference, object_aggregation)
        aggregation_level = network_dimension['id']
        time_dimension = self.prepare_time_dimension(
            counter_reference, aggregation_level, object_level, time_aggregation)
        report = self.api.get_reports_result(
            time_filter, object_filters, columns, network_dimension, time_dimension)
        return self._convert_report(report)

    def get_kpis_report(self, technology, kpis, filter_by, mo_names, object_aggregation, time_aggregation,
                        kpis_type='all', shared=False, time_filter='absolute', **kwargs):
        """
        Perform on-the-fly report and return PM KPIs statistics.

        Configuration of parameters and their values correspond to the `Add To New Board` wizard \
        of `Performance Manage+` application.
        Technology and KPI identifier values are accessible in `View Details` of each KPI.

        .. note::

            No idea how to configure parameter?
            Just set a dummy value, run script and follow a hint returned in the exception.

        Example output::

            [
                {
                    'Alarms_period_duration': 1440.0,
                    'LTE_39a': None,
                    'dn': 'PLMN-PLMN/MRBTS-1',
                    'mrbts_gid': '100001',
                    'mrbts_name': '1',
                    'period_start_time': '2022-02-22 00:00:00.0'
                }
            ]

        :param string technology: Technology name, e.g., ``Nokia LTE 24R2``
        :param string|list(string) kpis: KPI identifier(s), e.g.,
            ``Alarms_period_duration`` or ``['LTE_37a', 'LTE_39a']``.
        :param string filter_by: Item from `Filer by` list at `Object selection` stage
            of `Add To New Board` wizard, e.g., ``MRBTS``.
        :param string|list(string) mo_names: Managed object name(s), e.g., ``PLMN-PLMN/MRBTS-1``
            or ``['PLMN-PLMN/MRBTS-1', 'PLMN-PLMN/MRBTS-2']``.
            Item from `Available objects` list at `Object selection` stage of `Add To New Board` wizard.
        :param string object_aggregation: Object aggregation name, e.g., ``MRBTS``.
            Item from `Object` list at `Aggregation` stage of `Add To New Board` wizard.
        :param string time_aggregation: Time aggregation name, e.g., ``RAW``.
            Item from `Time` list at `Aggregation` stage of `Add To New Board` wizard.
        :param string kpis_type: The type of KPIs. Allowed values: ``all``, ``custom`` and ``system``
        :param bool shared: Specifies if shared KPIs should be taken into account
        :param string time_filter: Corresponds to `Time selection` stage of `Add To New Board` wizard.
            Allowed value: ``relative``, ``absolute``, ``realtime``, ``today``, ``currentMonth``
            or ``previousMonth``.

        :kwargs: Depend on the set ``time_filter`` as follows:

            - time_from (string): Mandatory for ``relative`` time filter.
                Allowed values: ``NOW`` or ``MIDNIGHT``.
            - time_amount (int): Mandatory for ``relative`` time filter.
            - time_period (string): Mandatory for ``relative`` time filter.
                Allowed values: ``MIN``, ``HOUR``, ``DAY``, ``WEEK`` or ``MONTH``.
            - start_time (datetime): Mandatory for ``absolute`` time filter.
            - end_time (datetime): Mandatory for ``absolute`` time filter.
            - look_back_period (int): Mandatory for ``realtime`` time filter (in minutes).

        :return: PM KPIs statistics.
        :rtype: list(dict)
        """
        time_filter = TimeFilter(time_filter, **kwargs).scheme
        columns = self.prepare_kpi_columns(technology, kpis, kpis_type, shared)
        kpi_reference = columns[0]['reference']
        object_level = self.get_object_level(kpi_reference, filter_by)
        object_filters = self.prepare_object_filters(technology, object_level, mo_names)
        network_dimension = self.prepare_network_dimension(kpi_reference, object_aggregation)
        aggregation_level = network_dimension['id']
        time_dimension = self.prepare_time_dimension(
            kpi_reference, aggregation_level, object_level, time_aggregation)
        report = self.api.get_reports_result(
            time_filter, object_filters, columns, network_dimension, time_dimension)
        return self._convert_report(report)
